style.css:
:root {
  --theme-bg-deep:        #1a0610;  /* page background */
  --theme-bg-surface:     #2b0f1c;  /* pin cards, panels */
  --theme-bg-surface-2:   #3d1626;  /* hovered / secondary surfaces */
  --theme-bg-surface-3:   #4a1c2c;  /* hover states on buttons/toggles */
  --theme-pink:           #f0a8c4;  /* primary buttons ("Save", CTAs) */
  --theme-pink-hover:     #e691b5;
  --theme-pink-pressed:   #d67ba3;
  --theme-text:           #f5e3ea;  /* primary text */
  --theme-text-subtle:    #c99aab;  /* secondary text, placeholders */
  --theme-border:         rgba(240, 168, 196, 0.16);
}

/* --------------------------------------------------------------------
   2. PINTEREST DESIGN-SYSTEM TOKENS
   Pinterest's UI (Gestalt) is built on CSS custom properties —
   re-pointing the core ones recolors buttons, banners, avatars, toggles,
   badges and text across the site consistently.
   -------------------------------------------------------------------- */
:root {
  /* base neutral scale */
  --base-color-grayscale-0:   var(--theme-bg-deep)    !important;
  --base-color-grayscale-50:  var(--theme-bg-surface)  !important;
  --base-color-grayscale-100: var(--theme-bg-surface-2) !important;
  --base-color-grayscale-150: #563943 !important;
  --base-color-grayscale-200: #875a69 !important;

  /* semantic background / text */
  --sema-color-background-default:   var(--theme-bg-deep)    !important;
  --sema-color-background-elevation: var(--theme-bg-surface)  !important;
  --sema-color-background-primary:   var(--theme-pink)        !important;
  --sema-color-hover-background-primary:   var(--theme-pink-hover)   !important;
  --sema-color-pressed-background-primary: var(--theme-pink-pressed) !important;
  --sema-color-pressed-background-secondary: var(--theme-bg-surface-3) !important;
  --sema-color-text-default: var(--theme-text)        !important;
  --sema-color-text-subtle:  var(--theme-text-subtle) !important;
  --sema-color-text-primary: var(--theme-pink)         !important;

  /* buttons ("Save", follow, primary CTAs) */
  --comp-button-color-background-primary-default:         var(--theme-pink)         !important;
  --comp-button-color-pressed-background-primary-default:  var(--theme-pink-pressed) !important;
  --comp-button-color-pressed-background-primary-selected: #2c1118 !important;
  --comp-button-color-background-secondary-default:        var(--theme-bg-surface-2) !important;
  --comp-button-color-hover-background-secondary-default:   var(--theme-bg-surface-3) !important;
  --comp-button-color-pressed-background-secondary-default: #5c2436 !important;
  --comp-button-color-text-transparent-disabled: #875a69 !important;

  /* notification badge / indicator dot */
  --comp-indicator-color-background-default: #ff6b95 !important;

  /* banners, toggles, avatars */
  --comp-bannerslim-color-background-default-expanded: var(--theme-bg-surface) !important;
  --comp-bannerslim-color-text-body-warning-expanded:  var(--theme-text)        !important;
  --comp-buttontoggle-color-hover-background-default-enabled-strong: var(--theme-bg-surface-3) !important;
  --comp-buttontoggle-color-hover-background-default-enabled-subtle: var(--theme-bg-surface)    !important;
  --comp-avatar-color-hover-background-default: var(--theme-bg-surface-3) !important;
}

/* --------------------------------------------------------------------
   3. STRUCTURAL LAYOUT — header, search, feed, pin cards, footer
   -------------------------------------------------------------------- */
html, body {
  background: var(--theme-bg-deep) !important;
}

[data-test-id="header"],
[data-test-id="header-PartnerHeader"] {
  background: #24081a !important;
  border-bottom: 1px solid var(--theme-border) !important;
  box-shadow: 0 2px 18px rgba(0, 0, 0, 0.45) !important;
}

[data-test-id="search-box-container"] {
  background: var(--theme-bg-surface-2) !important;
  border-radius: 24px !important;
}
[data-test-id="search-box-container"] input {
  background: transparent !important;
  color: var(--theme-text) !important;
}
[data-test-id="search-box-container"] input::placeholder {
  color: var(--theme-text-subtle) !important;
}

[data-test-id="homefeed-feed"],
[data-test-id="masonry-container"],
[data-test-id="max-width-container"] {
  background: var(--theme-bg-deep) !important;
}

[data-test-id="pin"],
[data-test-id="pinWrapper"] {
  background: var(--theme-bg-surface) !important;
  border-radius: 16px !important;
}
[data-test-id="pin"]:hover,
[data-test-id="pinWrapper"]:hover {
  box-shadow: 0 0 0 2px rgba(240, 168, 196, 0.55), 0 8px 24px rgba(0, 0, 0, 0.5) !important;
}
[data-test-id="pinrep-footer"] {
  background: var(--theme-bg-surface) !important;
  color: var(--theme-text) !important;
}

[data-test-id="footer"],
[data-test-id="floating-footer"] {
  background: #24081a !important;
  border-top: 1px solid var(--theme-border) !important;
}

[data-test-id="one-tap-desktop"],
[data-test-id="pincard-oneTap-with-link"] {
  background: linear-gradient(180deg, rgba(26, 6, 16, 0) 0%, rgba(26, 6, 16, 0.85) 100%) !important;
}

/* --------------------------------------------------------------------
   4. NICE TOUCHES — selection & scrollbar
   -------------------------------------------------------------------- */
::selection {
  background: var(--theme-pink) !important;
  color: var(--theme-bg-deep) !important;
}

::-webkit-scrollbar { width: 12px; height: 12px; }
::-webkit-scrollbar-track { background: var(--theme-bg-deep); }
::-webkit-scrollbar-thumb {
  background: #6b2438;
  border-radius: 8px;
  border: 2px solid var(--theme-bg-deep);
}
::-webkit-scrollbar-thumb:hover { background: #8a3450; }
